    flex-wrap: wrap;
    gap: 8px;
  }

  .benefit-tag {
    /* ZMIANA: Ciemny grafit zamiast czarnego */
    background: #333333; 
    color: #ffffff;
    padding: 6px 15px;
    border-radius: 50px;
    border: 1px solid rgba(255, 255, 255, 0.1);
