  @media (max-width: 600px) {
    .product-info-extended {
      margin: 20px 0;
    }

    .info-title {
      font-size: 12px;
      margin-bottom: 10px;
    }

    .action-description {
      font-size: 14px;
      line-height: 1.5;
    }

    .benefit-tag {
      font-size: 11px;
      padding: 5px 12px;
    }
  }
</style>

