    background: none;

    border: none;

    padding: 0;

    text-decoration: underline;

    cursor: pointer;

    font-family: inherit;

    text-align: left;

    transition: color 0.2s;

  }



  .status-link-btn:hover { color: #000; }



  /* MODAL STYLE */

  .map-modal-overlay {

    position: fixed;

    top: 0; left: 0; width: 100%; height: 100%;

    background: rgba(0, 0, 0, 0.7);

    backdrop-filter: blur(4px);

    z-index: 2147483647;

    display: flex;

    justify-content: center;

    align-items: center;

    padding: 20px;

    opacity: 0;

    visibility: hidden;

    pointer-events: none;

    transition: all 0.3s ease;

  }

  .map-modal-overlay.is-active { opacity: 1; visibility: visible; pointer-events: auto; }

  .map-modal-content {

    background: #fff;

    width: 100%;

    max-width: 900px;

    height: 80vh;

    position: relative;

    padding: 30px;

    transform: translateY(20px);

    transition: transform 0.4s ease;

  }

  .map-modal-overlay.is-active .map-modal-content { transform: translateY(0); }

  .map-modal-header { font-weight: 700; font-size: 16px; text-transform: uppercase; margin-bottom: 20px; }

  .map-modal-close { position: absolute; top: 15px; right: 20px; background: none; border: none; font-size: 32px; cursor: pointer; }

  .map-container-inner { flex: 1; height: calc(100% - 60px); border: 1px solid #f0f0f0; }



